#!/usr/bin/env python3
"""
Round 106b (culprits), 28 September 2026. Needs round 105b.

The View and 3D terrain boxes rearranged, Turn on every at the bottom and lighter,
a loading mark, sublayers shown when ticked, the Attacks On Activists layers.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 106b (28 September)\n\nNeeds round 105b. Tiles patch round106b_tiles.py beside it (attacks/*.geojson).\n\n- View box: Globe, Flat map, Layer colours (narrow, under Flat map), compass\n  with Place names, Snap back and Leave Earth (the wide colour menu had pushed\n  them out of the box). New box "3D terrain": the tick, the notes on moving in\n  3D, then Raise figures as heights with a line saying what it does.\n- Turn on every: under the layers (box.after); says "Turning off" when\n  turning off; catalogue rows for boundaries or figures by country, province or\n  district are national; a Shapes row that turns out to draw countries\n  (drawsCountries: country codes or names) is untucked and filed national.\n- lighterPointSources: a GeoJSON source of points only gets maxzoom 12, so\n  zooming in no longer re-cuts hundreds of sources. mapBusyMark: "Loading..."\n  at the top of the map while it reads; a notice on WebGL context loss.\n- revealSubRows: ticking a row with sublayers (group kids, facets, type rows)\n  opens them and scrolls the menu to show them (trusted events only).\n- Attacks On Activists (owner\'s collection): attacks_gw_killings,\n  attacks_land_resistance, attacks_frontline, attacks_cimi, attacks_caci,\n  attacks_cpt_violence, attacks_cpt_threatened, attacks_cpt_massacres,\n  attacks_public_agencies (Of individuals > Of humans),\n  attacks_slave_labour_states (Slavery > Cases and enforcement),\n  police_stations_latam (Law enforcement). autoGroups colours kinds by count.\n  Land of Resistance dates of birth and photo links left off.\n- Script version app.js?v=997.\n\n'
HEAD = "## Round 106b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round106b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 105b" not in text:
        sys.exit("round106b: round 105b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round106b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round106b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round106b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 105b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
